def cfm(number,title,cc,summary,scope):
 return dict(id=f'cfm-nt-2023-{number}',title=title,url=f'https://www.churchofjesuschrist.org/study/manual/come-follow-me-for-sunday-school-new-testament-2023/{number}?lang=eng',author='The Church of Jesus Christ of Latter-day Saints',publisher='The Church of Jesus Christ of Latter-day Saints',year=2023,category='LDS Come, Follow Me',perspective='lds',summary=summary,limits='Coverage follows the actual lesson body rather than its title. Church applications to callings and ordinances remain distinct from independent historical evidence. The lesson\x27s naming of Paul does not settle authorship. Linked videos, talks, and Restoration texts were not independently reviewed.',chapterCoverage=cc,reviewed=dict(date=date,scope=scope))
sources=[cfm(45,'October 30–November 5 · Hebrews 1–6',[1,2,3,4,5],'The lesson connects Christ\x27s suffering with help, responsive hearts, and called service.','Complete lesson body and resource list read. Actual discussion covers chapters one through five. Chapter six is not separately discussed.'),cfm(46,'November 6–12 · Hebrews 7–13',[7,8,9,10,11],'The lesson connects ordinances with Christ and faith with trust in unfinished promises.','Complete lesson body and included Holland quotation read. Actual discussion covers chapters seven through eleven. Linked full talks and videos were not reviewed.')]
